#include "ark/agent_benchmark.hpp"
#include "ark/agent.hpp"
#include "ark/agent_team.hpp"
#include <fstream>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <thread>
using V=arkjson::Value;
static void check(bool condition,const char* message){if(!condition)throw std::runtime_error(message);}
static V read(const std::string& path){std::ifstream stream(path);check((bool)stream,"fixture file present");std::ostringstream text;text<<stream.rdbuf();V value;check(arkjson::parse(text.str(),value),"fixture JSON valid");return value;}
template<class F>static void rejects(F action,const char* message){bool failed=false;try{action();}catch(const std::exception&){failed=true;}check(failed,message);}
static V json(const char* text){V value;check(arkjson::parse(text,value),"test JSON valid");return value;}
static V tool(const std::string& name,V args){auto result=json(R"({"status":"completed","output":[]})");auto output=*result.find("output");V call=V::makeObj();call.set("type",V::makeStr("function_call"));static std::atomic_uint callSerial{0};call.set("call_id",V::makeStr("call-"+name+"-"+std::to_string(++callSerial)));call.set("name",V::makeStr(name));call.set("arguments",V::makeStr(args.dump()));output.arr.push_back(call);result.set("output",output);return result;}
static V done(){return json(R"({"status":"completed","output":[{"type":"message","role":"assistant","content":[{"type":"output_text","text":"Turn complete."}]}]})");}
static void scopedAssignments(){
    ark::AgentSession session;session.suppressIterationHistory();check(!session.call("doc_apply",json(R"({"expected_revision":0,"commands":[{"op":"feature.add","name":"Block","type":"box","p":{"dx":10,"dy":20,"dz":30}}]})")).find("isError")->b,"scope baseline accepted");
    ark::AgentTeamConfig config;config.focusedWorkflow=true;config.orchestratedStart=true;config.maxWorkers=1;unsigned leadRound=0,designerRound=0,contextCalls=0;bool received=false,staleRejected=false,missingRejected=false,tooManyRejected=false;
    ark::AgentTeamRole lead;lead.id="engineer";lead.label="engineer";lead.canWrite=true;lead.discipline=ark::AgentTeamDiscipline::Orchestrator;lead.assistant.model="offline-scope";
    lead.transport=[&](const auto&,const V& request,const auto*){auto n=++leadRound;if(n==2)staleRejected=request.dump().find("Revision conflict")!=std::string::npos;if(n==3)missingRejected=request.dump().find("REFERENCE_MISSING")!=std::string::npos;if(n==4)tooManyRejected=request.dump().find("1..8 existing")!=std::string::npos;
        if(n==1)return tool("team_send",json(R"({"to":"designer","kind":"assignment","message":"Inspect Block only.","scope":{"ids":["Block"],"expected_revision":0}})"));
        if(n==2)return tool("team_send",json(R"({"to":"designer","kind":"assignment","message":"Inspect Block only.","scope":{"ids":["missing"],"expected_revision":1}})"));
        if(n==3)return tool("team_send",json(R"({"to":"designer","kind":"assignment","message":"Inspect Block only.","scope":{"ids":[1,2,3,4,5,6,7,8,9],"expected_revision":1}})"));
        if(n==4)return tool("team_send",json(R"({"to":"designer","kind":"assignment","message":"Inspect Block only and report evidence.","scope":{"ids":["Block"],"expected_revision":1}})"));
        if(n==6)return tool("team_finish_goal",json(R"({"state":"completed","summary":"Scoped existing-object inspection integrated; no write ownership enforcement or manufacturing claim."})"));return done();};
    ark::AgentTeamRole designer=lead;designer.id="designer";designer.label="designer";designer.discipline=ark::AgentTeamDiscipline::PartDesigner;
    designer.transport=[&](const auto&,const V& request,const auto*){auto n=++designerRound;if(n==1){received=request.dump().find("origin_revision")!=std::string::npos&&request.dump().find("requires_reinspection")!=std::string::npos&&request.dump().find("ownership_enforced")!=std::string::npos&&request.dump().find("Block")!=std::string::npos;return tool("doc_info",json(R"({"detail":"design"})"));}if(n==2)return tool("team_report_task",json(R"({"state":"completed","summary":"Inspected scoped Block at current revision 1; no mutation."})"));if(n==3)return tool("team_send",json(R"({"to":"engineer","kind":"report","message":"Block inspection complete at revision 1; no mutation."})"));return done();};config.roles={lead,designer};ark::AgentTeam team;
    team.start(config,"Inspect only existing Block with a specific scoped assignment",ark::AgentSession::tools(),[&](const auto& name,const V& args){if(name=="object_context")++contextCalls;return session.call(name,args);});check(team.waitIdleFor(std::chrono::seconds(5)),"scoped focused workflow completed");auto snapshot=team.snapshot();if(!received||!staleRejected||!missingRejected||!tooManyRejected)throw std::runtime_error("scope flags received="+std::to_string(received)+" stale="+std::to_string(staleRejected)+" missing="+std::to_string(missingRejected)+" oversized="+std::to_string(tooManyRejected)+" context_calls="+std::to_string(contextCalls));check(contextCalls==3&&session.revision==1,"context reads serialized without mutating baseline");check(snapshot.goalDeclared&&snapshot.goalState==ark::AgentGoalState::Completed&&snapshot.unresolvedErrors==0,"corrected assignment integrated without unresolved failures");
}
int main(){try{
    const std::string root=ARK_SOURCE_DIR;auto suiteValue=read(root+"/benchmarks/agent_briefs_v1.json");auto suite=ark::parseAgentBenchmarkSuite(suiteValue);check(suite.cases.size()==30,"thirty distinct versioned synthetic briefs");auto preflight=ark::preflightAgentBenchmark(suite);if(!preflight.find("passed")->b)throw std::runtime_error(preflight.dump());
    auto config=ark::parseAgentBenchmarkConfig(read(root+"/benchmarks/offline.json"));check(config.repetitions==3&&config.assistant.maxRounds==0,"three repetitions without production round budgets");config.repetitions=1;config.caseIds={"B01","P01","A01"};unsigned persisted=0;auto report=ark::runAgentBenchmark(suite,config,false,[&](const V& row){check(row.find("transport")->str=="offline_scripted_harness","offline classification");check(row.find("cost")->isNull(),"no invented pricing");check(row.find("usage")->find("reported_responses")->num==0&&row.find("usage")->find("missing_responses")->num>0,"missing scripted usage stays missing");check(row.find("performance")->find("provider_requests")->num>=3,"real connector round receipts");check(row.find("performance")->find("request_bytes")->num>0,"request envelope measured");check(row.find("tool_receipts")->arr.size()>=2,"actual native executor receipts persisted");++persisted;});check(persisted==9&&report.find("accepted_count")->num==9,"three tasks across three real strategies accepted");
    auto broken=suite;broken.cases={suite.cases[0]};broken.cases[0].checks.arr[2].set("equals",V::makeNum(123));config.caseIds={"B01"};auto failed=ark::runAgentBenchmark(broken,config);check(failed.find("failed_attempt_count")->num==3&&failed.find("attempt_count")->num==3,"failed attempts retained in every strategy");check(!ark::preflightAgentBenchmark(broken).find("passed")->b,"invalid reference postcondition detected");
    auto duplicate=suiteValue;auto cases=*duplicate.find("cases");cases.arr.push_back(cases.arr[0]);duplicate.set("cases",cases);rejects([&]{ark::parseAgentBenchmarkSuite(duplicate);},"duplicate case IDs rejected");auto invalid=read(root+"/benchmarks/offline.json");invalid.set("repetitions",V::makeNum(0));rejects([&]{ark::parseAgentBenchmarkConfig(invalid);},"zero repetition rejected");config.caseIds={"absent"};rejects([&]{ark::runAgentBenchmark(suite,config);},"unknown case filter rejected");
    config.caseIds={"B01"};config.strategies={"Single"};config.offlineTransport=[](const auto&,const V&,const auto*){return json(R"({"status":"incomplete","output":[],"usage":{"input_tokens":20,"output_tokens":4,"total_tokens":24}})");};auto rejectedProvider=ark::runAgentBenchmark(suite,config);const auto& rejectedRow=rejectedProvider.find("attempts")->arr.front();check(!rejectedRow.find("accepted")->b&&rejectedRow.find("usage")->find("total_tokens")->num==24,"failed billed provider response retained");
    config.deadlineSeconds=1;config.offlineTransport=[](const auto&,const V&,const std::atomic_bool* cancel)->V{while(!cancel->load())std::this_thread::sleep_for(std::chrono::milliseconds(5));throw std::runtime_error("Host benchmark window cancelled provider");};auto cancelled=ark::runAgentBenchmark(suite,config);const auto& cancelledRow=cancelled.find("attempts")->arr.front();check(cancelledRow.find("timed_out")->b&&!cancelledRow.find("accepted")->b&&cancelledRow.find("final_revision")->num==1,"host timeout cancels without pretending completion or changing baseline");check(cancelledRow.find("usage")->find("missing_responses")->num==1&&cancelledRow.find("performance")->find("provider_requests")->num==1,"timeout records unknown usage and failed request timing");rejects([&]{ark::runAgentBenchmark(suite,config,true);},"live cannot use offline test seam");scopedAssignments();
    auto visualFixture=read(root+"/examples/pneumatic-cylinder.arkops");unsigned visionRounds=0;bool actualPixels=false;config.deadlineSeconds=10;config.offlineTransport=[&](const auto&,const V& request,const auto*){if(++visionRounds==1)return tool("snapshot",json(R"({"view":"iso"})"));actualPixels=request.dump().find("input_image")!=std::string::npos&&request.dump().find("data:image/png;base64,")!=std::string::npos;return done();};auto vision=ark::runAgentVisionSmoke(*visualFixture.find("arguments")->find("commands"),config);check(actualPixels&&vision.find("completed")->b&&vision.find("document_unchanged")->b,"synthetic mechanism pixels pass through production assistant without mutation");check(vision.find("captures")->arr.front().find("png_bytes")->num>1000&&!vision.find("pixels_in_completed_provider_turn")->b,"real PNG receipt recorded; offline vision never becomes LLM evidence");
    std::cout<<"agent-benchmark: 30 native preflights, 9 accepted runs, retained failures, cancellation, scoped delegation and image delivery passed\n";return 0;
}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
